import{_ as t,o as i,c as a,ae as o}from"./chunks/framework.Czhw_PXq.js";const g=JSON.parse('{"title":"Requirements Analysis & UML Modeling Standards","description":"","frontmatter":{},"headers":[],"relativePath":"standards/requirements_UML.md","filePath":"standards/requirements_UML.md"}'),n={name:"standards/requirements_UML.md"};function r(s,e,l,d,c,m){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="requirements-analysis-uml-modeling-standards" tabindex="-1">Requirements Analysis &amp; UML Modeling Standards <a class="header-anchor" href="#requirements-analysis-uml-modeling-standards" aria-label="Permalink to &quot;Requirements Analysis &amp; UML Modeling Standards&quot;">​</a></h1><p>Use these guidelines to define what to build (Requirements) and how to visualize the solution (UML) before and during development.</p><h2 id="_1-requirements-analysis-the-foundation" tabindex="-1">1. Requirements Analysis: The Foundation <a class="header-anchor" href="#_1-requirements-analysis-the-foundation" aria-label="Permalink to &quot;1. Requirements Analysis: The Foundation&quot;">​</a></h2><p>A requirement is a condition the system must meet. [cite_start]It must be clear, useful, and testable[cite: 1802, 1803].</p><h3 id="a-requirements-typology" tabindex="-1">A. Requirements Typology <a class="header-anchor" href="#a-requirements-typology" aria-label="Permalink to &quot;A. Requirements Typology&quot;">​</a></h3><ul><li>[cite_start]<strong>Functional Requirements (FR):</strong> Define <em>what</em> the system does (e.g., &quot;The system must allow PDF uploads&quot;)[cite: 1810, 1811].</li><li>[cite_start]<strong>Non-Functional Requirements (NFR):</strong> Define <em>how</em> the system behaves—quality, performance, security (e.g., &quot;Passwords must be encrypted&quot;)[cite: 1812, 1813].</li><li>[cite_start]<strong>Constraints:</strong> Mandatory technical or business limitations (e.g., &quot;Must comply with GDPR/ISO27001&quot;)[cite: 1814, 1815].</li><li>[cite_start]<strong>Business &amp; Data Requirements:</strong> Needs driven by commercial strategy or integration (e.g., Stripe or external API connections)[cite: 1816].</li></ul><h3 id="b-agile-definition-tools" tabindex="-1">B. Agile Definition Tools <a class="header-anchor" href="#b-agile-definition-tools" aria-label="Permalink to &quot;B. Agile Definition Tools&quot;">​</a></h3><ul><li>[cite_start]<strong>User Stories:</strong> &quot;As a [USER], I want [GOAL] so that [BENEFIT]&quot;[cite: 1819, 1820].</li><li>[cite_start]<strong>Acceptance Criteria (Gherkin):</strong> Use the <strong>Given - When - Then</strong> structure to define completion[cite: 1821, 1822]. <ul><li>[cite_start]<em>Example:</em> &quot;GIVEN I am logged in, WHEN I click &#39;Analyze&#39;, THEN I see the compliance report&quot;[cite: 1823].</li></ul></li><li>[cite_start]<strong>Prioritization (MoSCoW):</strong> Categorize into <strong>Must</strong> have, <strong>Should</strong> have, <strong>Could</strong> have, and <strong>Won&#39;t</strong> have[cite: 1828, 1829].</li></ul><h2 id="_2-uml-unified-modeling-language-visualization" tabindex="-1">2. UML (Unified Modeling Language): Visualization <a class="header-anchor" href="#_2-uml-unified-modeling-language-visualization" aria-label="Permalink to &quot;2. UML (Unified Modeling Language): Visualization&quot;">​</a></h2><p>[cite_start]UML is the standard for mapping system logic to detect errors before coding[cite: 1832, 1833].</p><h3 id="key-diagrams-for-implementation" tabindex="-1">Key Diagrams for Implementation <a class="header-anchor" href="#key-diagrams-for-implementation" aria-label="Permalink to &quot;Key Diagrams for Implementation&quot;">​</a></h3><ul><li><strong>Use Case Diagrams:</strong> Show interactions between Actors (Users) and the system. [cite_start]Includes pre-conditions and alternative flows (errors)[cite: 1837, 1838].</li><li>[cite_start]<strong>Sequence &amp; Process Diagrams:</strong> Show chronological order of interactions and business logic[cite: 1839].</li><li>[cite_start]<strong>Class &amp; Component Diagrams:</strong> Map technical architecture and data structures[cite: 1840].</li></ul><h3 id="recommended-tools" tabindex="-1">Recommended Tools <a class="header-anchor" href="#recommended-tools" aria-label="Permalink to &quot;Recommended Tools&quot;">​</a></h3><ul><li><strong>Text-based (Recommended):</strong> <strong>Mermaid</strong> or PlantUML. [cite_start]These allow versioning diagrams alongside code in Git[cite: 1844, 1845].</li><li>[cite_start]<strong>Visual:</strong> Draw.io or Lucidchart for rapid prototyping[cite: 1843].</li></ul><h2 id="_3-implementation-workflow" tabindex="-1">3. Implementation Workflow <a class="header-anchor" href="#_3-implementation-workflow" aria-label="Permalink to &quot;3. Implementation Workflow&quot;">​</a></h2><ol><li>[cite_start]<strong>Early Validation:</strong> Use prototypes or interviews to clarify the problem[cite: 1848].</li><li>[cite_start]<strong>Agile Cycles (Sprints):</strong> Break development into increments rather than planning everything upfront (avoiding pure Waterfall)[cite: 1851, 1852].</li><li><strong>Verification vs. Validation:</strong> * <em>Verification:</em> Did we build the product correctly? (Unit Tests, Code Review) [cite_start][cite: 1854]. <ul><li><em>Validation:</em> Did we build the right product? (User Demos, Business Metrics) [cite_start][cite: 1855].</li></ul></li></ol>',16)])])}const h=t(n,[["render",r]]);export{g as __pageData,h as default};
